import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.BDCokyix.js";const u=JSON.parse('{"title":"Agent Contract Ownership","description":"","frontmatter":{},"headers":[],"relativePath":"contracts/agent-ownership.md","filePath":"contracts/agent-ownership.md","lastUpdated":1780254295000}'),r={name:"contracts/agent-ownership.md"};function n(s,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="agent-contract-ownership" tabindex="-1">Agent Contract Ownership <a class="header-anchor" href="#agent-contract-ownership" aria-label="Permalink to &quot;Agent Contract Ownership&quot;">​</a></h1><p><strong>Status:</strong> Documented</p><h2 id="decision-agentd-is-not-a-model-provider" tabindex="-1">Decision: agentd is not a model provider <a class="header-anchor" href="#decision-agentd-is-not-a-model-provider" aria-label="Permalink to &quot;Decision: agentd is not a model provider&quot;">​</a></h2><p>The desktop agent surface has a compatibility proto for local helpers, but <code>soma-agentd</code> no longer owns model-provider behavior — and the surface itself has changed: <code>soma-agentd</code> is now a <strong>library</strong> embedded by the Tauri host&#39;s <code>desktop-agent</code> crate, not a separate process with a gRPC-over-Unix-socket surface.</p><h3 id="path-1-agentd-library-in-process-via-desktop-agent" tabindex="-1">Path 1: agentd library (in-process via <code>desktop-agent</code>) <a class="header-anchor" href="#path-1-agentd-library-in-process-via-desktop-agent" aria-label="Permalink to &quot;Path 1: agentd library (in-process via `desktop-agent`)&quot;">​</a></h3><ul><li><strong>Surface:</strong> in-process calls into the embedded agent runtime (<code>agentStatus</code>, <code>listModels</code>, <code>resolveDrift</code>), surfaced to the renderer through <code>@soma/sdk</code>.</li><li><strong>Proto:</strong> <code>proto/agent/v1/agent.proto</code> — a Rust-only record-shape reference; the agentd library no longer serves it as a gRPC server.</li><li><strong>Use case:</strong> Yjs drift resolution and lightweight status.</li><li><strong>Features fully bound to the library:</strong><ul><li><code>agentStatus</code> / <code>listModels</code> (the latter returns an empty list)</li><li><code>resolveDrift</code> (Yjs merge)</li></ul></li><li><strong>Background tasks</strong> that used to be persisted in a <code>soma-agentd</code> SQLite table are tracked by the host&#39;s <code>desktop-agent</code> crate.</li></ul><h3 id="path-2-openai-compatible-http" tabindex="-1">Path 2: openai-compatible (HTTP) <a class="header-anchor" href="#path-2-openai-compatible-http" aria-label="Permalink to &quot;Path 2: openai-compatible (HTTP)&quot;">​</a></h3><ul><li><strong>Protocol:</strong> HTTP REST to OpenAI-compatible endpoints</li><li><strong>Use case:</strong> Direct provider access (Ollama, OpenAI, etc.)</li><li><strong>Features that bypass the agent library:</strong><ul><li><code>chatStream</code></li><li><code>listModels</code> (via <code>/models</code> endpoint)</li><li><code>rerank</code> (via <code>/embeddings</code> + cosine similarity)</li></ul></li></ul><h2 id="why-this-exists" tabindex="-1">Why This Exists <a class="header-anchor" href="#why-this-exists" aria-label="Permalink to &quot;Why This Exists&quot;">​</a></h2><ol><li><strong>Clear ownership:</strong> the agent library remains a local helper, not a provider adapter.</li><li><strong>Flexibility:</strong> users may run local models via Ollama without changing the agent library.</li><li><strong>Cloud fallback:</strong> some deployments prefer direct cloud provider access.</li><li><strong>Per-workspace config:</strong> different spaces can use different providers.</li></ol><h2 id="contract-implications" tabindex="-1">Contract Implications <a class="header-anchor" href="#contract-implications" aria-label="Permalink to &quot;Contract Implications&quot;">​</a></h2><h3 id="stable-surface" tabindex="-1">Stable Surface <a class="header-anchor" href="#stable-surface" aria-label="Permalink to &quot;Stable Surface&quot;">​</a></h3><ul><li><code>resolveDrift</code> — Yjs-specific, always via the agent library.</li></ul><h3 id="compatibility-surface" tabindex="-1">Compatibility Surface <a class="header-anchor" href="#compatibility-surface" aria-label="Permalink to &quot;Compatibility Surface&quot;">​</a></h3><ul><li><code>listModels</code>: <ul><li>agent-library path: empty list</li><li>openai-compatible path: model IDs from <code>/models</code></li></ul></li></ul><h3 id="no-contract-provider-specific" tabindex="-1">No Contract (provider-specific) <a class="header-anchor" href="#no-contract-provider-specific" aria-label="Permalink to &quot;No Contract (provider-specific)&quot;">​</a></h3><ul><li>Model availability, capabilities, latency</li><li>These are inherently provider-specific and documented as such.</li></ul><h2 id="documentation-requirements" tabindex="-1">Documentation Requirements <a class="header-anchor" href="#documentation-requirements" aria-label="Permalink to &quot;Documentation Requirements&quot;">​</a></h2><p>When updating <code>agent.proto</code>:</p><ol><li>Mark library-bound features clearly in comments.</li><li>Document whether the method is local-helper-only or provider-backed.</li><li>Update desktop <code>AgentClient</code> only when desktop behavior changes.</li></ol><h2 id="future-considerations" tabindex="-1">Future Considerations <a class="header-anchor" href="#future-considerations" aria-label="Permalink to &quot;Future Considerations&quot;">​</a></h2><p>If streaming chat becomes a critical contract:</p><ol><li>Standardize streaming semantics in the explicit provider path.</li><li>Implement it in the explicit provider path or <code>somad bff</code>.</li><li>Add <code>chat_stream_mode</code> to <code>AgentRuntimeConfig</code> for explicit control.</li></ol><p>For now, the agent library exposes only Yjs drift resolution and status.</p>',24)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
